// Packages built by the real server (LIQo backend/tool/shopper-fixtures.mjs),
// read the way a download is: each loads, has the server's node count, reaches
// exactly the places the server expects at the same cost from the first exit,
// keeps one-way escalators one-way, leaves a wheelchair out behind a narrow
// door, and gives directions without throwing. The fixtures are regenerated by
// the web/backend session whenever its builder changes.
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:liqo_mobile/core/data/shopper_api.dart' show sha256Hex;
import 'package:liqo_mobile/core/engine/directions.dart';
import 'package:liqo_mobile/core/engine/graph.dart';
import 'package:liqo_mobile/core/engine/package/package_venue.dart';
import 'package:liqo_mobile/core/engine/routing.dart';
import 'package:liqo_mobile/features/map/providers/map_provider.dart';
import 'package:liqo_mobile/features/navigation/providers/nav_provider.dart';

import '../support/app.dart';

const dir = 'test/fixtures/published';

void main() {
  final names = [
    for (final f in Directory(dir).listSync().whereType<File>())
      if (f.path.endsWith('.json') && !f.path.endsWith('.expect.json')) f.uri.pathSegments.last.replaceAll('.json', ''),
  ]..sort();

  drawn();

  test('there are fixtures to check', () => expect(names, containsAll(['corridor', 'two-levels', 'rotated', 'doors'])));

  for (final name in names) {
    group(name, () {
      final bytes = File('$dir/$name.json').readAsBytesSync();
      final json = (jsonDecode(utf8.decode(bytes)) as Map).cast<String, Object?>();
      final expectJ = (jsonDecode(File('$dir/$name.expect.json').readAsStringSync()) as Map).cast<String, Object?>();
      final v = PackageVenue(json);
      // the package's node ids, as the engine keys them
      final keyOf = {
        for (final n in ((json['graph']! as Map)['nodes']! as List).cast<Map>()) n['id'].toString(): nk((n['lv'] as num).toInt(), (n['x'] as num).toDouble(), (n['y'] as num).toDouble()),
      };
      final from = keyOf[expectJ['from']]!;

      test('loads, with the server\'s node count (its checksum is over these very bytes)', () {
        expect(sha256Hex(bytes), hasLength(64));
        expect(v.graph.nodes.length, expectJ['nodeCount']);
        expect(v.places, isNotEmpty);
      });

      test('reaches exactly the expected places, at the expected cost from the first exit', () {
        final d = dijkstra(v.graph, from, const RouteOpts(throughStores: true)).d;
        final reached = {for (final p in v.places) if (p.nodes.any(d.containsKey)) p.id};
        expect(reached, (expectJ['reachable']! as List).toSet());
        for (final e in (expectJ['totals']! as Map).entries) {
          final p = v.placeById(e.key.toString())!;
          final best = p.nodes.where(d.containsKey).map((k) => d[k]!).reduce((a, b) => a < b ? a : b);
          expect(best, closeTo((e.value as num).toDouble(), 1e-3), reason: e.key.toString());
        }
      });

      test('one-way links stay one-way', () {
        for (final pair in (expectJ['oneWay']! as List).cast<List>()) {
          final a = keyOf[pair[0]]!, b = keyOf[pair[1]]!;
          expect(v.graph.adj[a]!.any((e) => e.to == b), isTrue, reason: '${pair[0]} -> ${pair[1]}');
          expect(v.graph.adj[b]!.any((e) => e.to == a && e.kind == 'hop'), isFalse, reason: 'no way back up ${pair[1]} -> ${pair[0]}');
        }
      });

      test('a wheelchair is left out where the server says', () {
        final d = dijkstra(v.graph, from, const RouteOpts(wheel: true)).d;
        final cannot = {for (final p in v.places) if (!p.nodes.any(d.containsKey)) p.id};
        expect(cannot, (expectJ['wheelchairUnreachable']! as List).toSet());
      });

      test('directions build for every reachable place', () {
        final start = v.graph.nodes[from]!;
        for (final id in (expectJ['reachable']! as List).cast<String>()) {
          final p = v.placeById(id)!;
          final r = routesTo(v.graph, p.id, p.nodes, Pos(start.lv, start.x, start.y), false, throughStores: true);
          expect(r, isNotEmpty, reason: id);
          expect(() => directionsOf(r.first, v), returnsNormally, reason: id);
        }
      });
    });
  }
}

/// Each server-built map, on the phone as a downloaded mall, drawn by the map screen: the whole
/// site, every floor, all floors stacked, and a route; no exception anywhere.
void drawn() {
  for (final name in ['corridor', 'two-levels', 'rotated', 'doors']) {
    testWidgets('$name is drawn on the map screen', (tester) async {
      final bytes = File('$dir/$name.json').readAsBytesSync();
      final h = await pumpApp(tester, installed: ['bayview'], packages: {'bayview': bytes});
      await tester.tap(find.byKey(const ValueKey('tab-1')));
      await h.step(20);
      await tester.tap(find.text('Skip for now'));
      await h.step(30);
      final nav = h.c.read(navProvider.notifier), map = h.c.read(mapProvider.notifier), v = h.c.read(navProvider).v;
      for (var lv = 0; lv < v.levelCount; lv++) {
        h.c.read(mapProvider).cam.zoom = 4 * v.ratio;
        map.showLevel(lv);
        await h.step(10);
      }
      map.toggleStack();
      await h.step(40);
      map.toggleStack();
      await h.step(40);
      final exit = v.graph.nodes[v.exits.first.node]!;
      nav.refineAt(exit.lv, exit.x, exit.y);
      nav.startTo(v.places.lastWhere((p) => p.kind == 'store').id);
      await h.step(30);
      expect(h.c.read(navProvider).route, isNotNull);
      expect(tester.takeException(), isNull);
    });
  }
}
